#!/bin/sh
# Writes src/js/config.js from environment variables, for hosts that build the site
# (Cloudflare Pages, Netlify, Vercel). Set these in the host's dashboard and use
# `sh scripts/write-config.sh` as the build command:
#   SUPABASE_URL                 https://<project-ref>.supabase.co
#   SUPABASE_PUBLISHABLE_KEY     sb_publishable_...
#   PORTAL_URL                   optional, e.g. https://portal.example.com/
set -eu
: "${SUPABASE_URL:?Set SUPABASE_URL}"
: "${SUPABASE_PUBLISHABLE_KEY:?Set SUPABASE_PUBLISHABLE_KEY}"
cd "$(dirname "$0")/.."
cat > src/js/config.js <<EOF
// Generated by scripts/write-config.sh. Do not commit.
window.APP_CONFIG = {
  supabaseUrl: "${SUPABASE_URL}",
  supabasePublishableKey: "${SUPABASE_PUBLISHABLE_KEY}",
  portalUrl: "${PORTAL_URL:-}",
};
EOF
echo "Wrote src/js/config.js"
